 const label=document.createElement('span');label.className='character-name';label.textContent=name;el.append(label);$('cast').append(el);
 let phase=0,bob=0,lean=0;const rig={update(dt,velocity,mode,reduced){phase+=dt*(velocity>1?11:3);const blend=1-Math.exp(-dt*14),moving=velocity>1,attack=mode==='work';bob+=((reduced?0:moving?-Math.abs(Math.sin(phase))*3:Math.sin(phase)*.35)-bob)*blend;lean+=((reduced?0:attack?Math.sin(phase*2)*7:moving?Math.sin(phase)*2:0)-lean)*blend;canvas.style.transform=`translateY(${bob}px) rotate(${lean}deg)`;}};
